'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),overlay=$('#overlay');
let W=1000,H=460,ground=365,state='ready',score=0,best=0,distance=0,speed=290,elapsed=0,spawn=1,items=[],particles=[],last=0,world=0,sound=false,audio;
try{best=Number(localStorage.getItem('raccoon-best'))||0}catch{}$('#best').textContent=best;
const player={x:155,y:ground,vy:0,onGround:true};
let seed=91;function random(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646}const stars=Array.from({length:55},()=>({x:random()*1000,y:random()*245,r:random()*1.3+.4}));
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function tree(x,y,size,color){ctx.fillStyle=color;ctx.fillRect(x-4*size,y-80*size,8*size,110*size);for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(x,y-(160-i*36)*size);ctx.lineTo(x-(36+i*12)*size,y-(60-i*28)*size);ctx.lineTo(x+(36+i*12)*size,y-(60-i*28)*size);ctx.fill()}}
function background(){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#142b2b');sky.addColorStop(1,'#355342');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);for(const s of stars){ctx.globalAlpha=.4+.3*Math.sin(elapsed+s.x);ellipse(s.x/W*W,s.y,s.r,s.r,'#e7e9c1')}ctx.globalAlpha=1;ellipse(W*.78,83,53,53,'#d9dfb509');ellipse(W*.78,83,41,41,'#d9dfb50a');ellipse(W*.78,83,27,27,'#e3dfb6');ellipse(W*.78+10,75,25,25,'#1c3430');for(let layer=0;layer<3;layer++){const space=layer===0?145:225;for(let i=-1;i<W/space+2;i++){let x=i*space-(world*(.1+layer*.16))%space;tree(x,ground-25+layer*13,.7+layer*.37,['#1d3933','#254335','#2d4c39'][layer])}}ctx.fillStyle='#3b553b';ctx.beginPath();ctx.moveTo(0,ground+9);for(let x=0;x<=W+20;x+=20)ctx.lineTo(x,ground+9+Math.sin((x+world*.15)*.012)*7);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();ctx.fillStyle='#64724a';ctx.fillRect(0,ground+10,W,3);ctx.fillStyle='#283d2e';ctx.fillRect(0,ground+16,W,H-ground);for(let i=0;i<35;i++){let x=(i*73-world*.8)%(W+100);if(x<0)x+=W+100;ellipse(x,ground+36+(i%5)*14,2+i%3,1,'#6d784b66')}for(let i=0;i<9;i++){let x=(i*137+Math.sin(elapsed*.5+i)*12)%W;ellipse(x,220+Math.sin(elapsed+i*3)*48,2,2,'#d6dd8c66')}}
function raccoon(x,y){ctx.save();ctx.translate(x,y);const run=state==='running'&&player.onGround?Math.sin(elapsed*17):0;ctx.rotate(player.onGround?0:-.08);ellipse(-5,8,39,6,'#10241f55');ctx.save();ctx.translate(-31,-20);ctx.rotate(-.35+run*.035);ellipse(-14,0,27,12,'#8a9381');ctx.strokeStyle='#424e49';ctx.lineWidth=7;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(-30+i*14,-10);ctx.lineTo(-30+i*14,10);ctx.stroke()}ctx.restore();ellipse(0,-24,29,23,'#899484');ellipse(7,-20,19,18,'#b2b9a0');ellipse(-13+run*4,-1,9,5,'#46554b');ellipse(19-run*4,-1,9,5,'#46554b');ellipse(10,-57,10,13,'#8e9887');ellipse(37,-55,9,12,'#8e9887');ellipse(10,-57,5,7,'#48554e');ellipse(37,-55,4,7,'#48554e');ellipse(25,-43,26,22,'#bac2aa');ellipse(27,-43,24,10,'#3c4945');ellipse(17,-44,3,4,'#172c28');ellipse(37,-44,3,4,'#172c28');ellipse(18,-45,1,1,'#fff');ellipse(38,-45,1,1,'#fff');ellipse(30,-32,13,8,'#d5d9bf');ellipse(35,-35,5,3,'#293b34');ctx.fillStyle='#a1aa72';ctx.fillRect(2,-28,29,5);ctx.beginPath();ctx.moveTo(7,-24);ctx.lineTo(0,-11);ctx.lineTo(12,-16);ctx.fill();ctx.restore()}
function acorn(x,y){ctx.save();ctx.translate(x,y);ctx.rotate(.25);ellipse(0,2,9,12,'#d9b46b');ellipse(0,-6,11,5,'#8c7345');ctx.strokeStyle='#a78c54';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(3,-15);ctx.stroke();ctx.restore()}
function mushroom(x,y){ctx.fillStyle='#d6c9a1';ctx.fillRect(x-5,y-22,10,24);ctx.fillStyle='#bc765d';ctx.beginPath();ctx.ellipse(x,y-23,23,18,0,Math.PI,0);ctx.fill();ellipse(x-10,y-30,4,3,'#e9cda2');ellipse(x+7,y-34,3,3,'#e9cda2');ellipse(x+13,y-26,3,2,'#e9cda2')}
function beep(freq){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.start();o.stop(audio.currentTime+.15)}catch{}}
function hud(){$('#score').textContent=score;$('#best').textContent=best;$('#distance').textContent=`${Math.floor(distance)} m 산책 중`}
function start(){score=0;distance=0;speed=290;elapsed=0;spawn=1.2;items=[];particles=[];player.y=ground;player.vy=0;player.onGround=true;state='running';overlay.classList.add('hidden');$('#pause').textContent='Ⅱ';hud()}
function jump(){if(state==='running'&&player.onGround){player.vy=-650;player.onGround=false;beep(370)}}
function show(title,text,button,icon){$('#overlay-title').textContent=title;$('#overlay-text').textContent=text;$('#start').innerHTML=button+' <span>→</span>';$('#overlay-icon').textContent=icon;overlay.classList.remove('hidden')}
function finish(){state='over';beep(140);if(score>best){best=score;try{localStorage.setItem('raccoon-best',String(best))}catch{}}hud();show('오늘도 멋진 산책이었어요',`${Math.floor(distance)}m를 걷고, 도토리 ${score/10}개를 모았어요. 다시 떠나볼까요?`,'다시 산책하기','✦')}
function pause(){if(state==='running'){state='paused';show('잠깐, 숨 고르기','작은 숲은 여기서 기다리고 있어요.','이어서 산책하기','☾');$('#pause').textContent='▶'}else if(state==='paused'){state='running';overlay.classList.add('hidden');$('#pause').textContent='Ⅱ'}}
$('#start').onclick=e=>{e.stopPropagation();state==='paused'?pause():start()};$('#pause').onclick=pause;$('#sound').onclick=()=>{sound=!sound;$('#sound').style.background=sound?'#e5e8b4':'';$('#sound').setAttribute('aria-label',sound?'소리 끄기':'소리 켜기');$('#sound').title=sound?'소리 끄기':'소리 켜기';beep(600)};
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','KeyW'].includes(e.code)){if(e.target instanceof HTMLButtonElement)return;e.preventDefault();if(e.repeat)return;if(state==='ready'||state==='over')start();else if(state==='running')jump();else if(state==='paused')pause()}if(e.code==='KeyP'||e.code==='Escape')pause()});canvas.addEventListener('pointerdown',e=>{e.preventDefault();jump()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='running')pause()});
function resize(){const rect=canvas.getBoundingClientRect();W=rect.width<650?Math.round(rect.width/rect.height*460):1000;canvas.width=W;canvas.height=H;player.x=W<650?85:155}window.addEventListener('resize',resize);resize();
function frame(now){let dt=Math.min((now-last)/1000,.033);last=now;if(state==='running'){elapsed+=dt;world+=speed*dt;distance+=speed*dt/35;speed=Math.min(475,290+distance*.9);player.vy+=1650*dt;player.y+=player.vy*dt;if(player.y>=ground){player.y=ground;player.vy=0;player.onGround=true}spawn-=dt;if(spawn<=0){const obstacle=Math.random()<.45;items.push({x:W+35,y:obstacle?ground:ground-70-Math.random()*50,type:obstacle?'mushroom':'acorn'});spawn=(1.05+Math.random()*.55)*290/speed}for(const item of items){item.x-=speed*dt;const hit=item.type==='mushroom'?Math.abs(item.x-(player.x+7))<32&&player.y>ground-37:Math.abs(item.x-(player.x+15))<34&&Math.abs(item.y-(player.y-37))<39;if(hit&&!item.taken){if(item.type==='mushroom'){finish();break}item.taken=true;score+=10;beep(750);for(let i=0;i<8;i++)particles.push({x:item.x,y:item.y,vx:(Math.random()-.5)*120,vy:-Math.random()*130,life:.6})}}items=items.filter(i=>i.x>-40&&!i.taken);hud()}background();for(const item of items){if(item.type==='acorn')acorn(item.x,item.y+Math.sin(elapsed*3+item.x*.01)*3);else mushroom(item.x,item.y)}raccoon(player.x,player.y);if(state==='running')for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;ctx.globalAlpha=Math.max(0,p.life/.6);ellipse(p.x,p.y,2,2,'#e4d59b')}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0);requestAnimationFrame(frame)}requestAnimationFrame(frame);
